---RefreshAnimtionBgByQuestId 根据关卡id刷新选中底的版式
---@param questId integer @ 关卡id
function GachaCoinQuestAnimationControll:RefreshAnimtionBgByQuestId(questId)
    local questConfig = GCQUtils.GetGachaCoinQuestConfigById(questId)
    if nil ~= questConfig then
        -- 关卡名
        self.QuestNameLabel.text = questConfig.label

        -- 底色
        local rgbStr = questConfig.rgb
        local rgbInfo = parse_strings(rgbStr, ';')
        self.SplitLine.color = XLuaUtils.HexToColor(rgbInfo[2])
        self.QuestNameLabel.color = XLuaUtils.HexToColor(rgbInfo[3])
        self.QuestNoLabel.color = XLuaUtils.HexToColor(rgbInfo[3])
        self.Text.color = XLuaUtils.HexToColor(rgbInfo[4])
        --for key, value in pairs(self.uiConfig) do
        --    value.color = XLuaUtils.HexToColor(rbgInfo[key])
        --end
    end
end


return GachaCoinQuestAnimationControll